import{_ as l,a0 as a,w as r,s as u,ao as o,I as p,x as t,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"深度操作系统成为首个支持人脸解锁的 Linux 发行版 | LCTT x X-CMD","titleTemplate":false,"description":"深度操作系统成为首个支持人脸解锁的 Linux 发行版 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"深度操作系统成为首个支持人脸解锁的 Linux 发行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"深度操作系统成为首个支持人脸解锁的 Linux 发行版 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220401 Deepin OS Becomes the First Linux Distro to Offer Face Unlock","title":"深度操作系统成为首个支持人脸解锁的 Linux 发行版","tag":"202204","desc":""},"relativePath":"202204/20220401 Deepin OS Becomes the First Linux Distro to Offer Face Unlock.md","filePath":"[post].md"}'),d={name:"202204/20220401 Deepin OS Becomes the First Linux Distro to Offer Face Unlock.md"};function m(f,e,x,w,h,T){const s=a("Link");return r(),u("div",null,[e[21]||(e[21]=o('<h1 id="深度操作系统成为首个支持人脸解锁的-linux-发行版" tabindex="-1">深度操作系统成为首个支持人脸解锁的 Linux 发行版 <a class="header-anchor" href="#深度操作系统成为首个支持人脸解锁的-linux-发行版" aria-label="Permalink to “深度操作系统成为首个支持人脸解锁的 Linux 发行版”">​</a></h1><blockquote><p>在提供现代桌面体验方面，深度占据了领先地位。</p></blockquote><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/04/deepin-20-5-release.png?w=1200&amp;ssl=1" alt=""></p><p>在深度问世时，人们都为它纯粹的漂亮界面而惊叹。</p><p>随着时间的推移，开发人员越来越有经验，他们把重点转移到了系统设计和功能上，力求在这些方面和其他的商业操作系统看齐，我指的是 Windows 和 macOS。深度是首个支持安卓应用和云同步等功能的发行版。</p><p>相信我，这是一件好事情。</p><p>Linux 发行版以各种桌面环境的形式向大众提供。深度看起来很主流，可以吸引年轻群体。</p><p>中国的深度开发团队的也有相同目标，因此深度发布了 20.5 版本，该版本主要亮点是面部识别。</p><h3 id="深度操作系统-20-5-的新功能" tabindex="-1">深度操作系统 20.5 的新功能 <a class="header-anchor" href="#深度操作系统-20-5-的新功能" aria-label="Permalink to “深度操作系统 20.5 的新功能”">​</a></h3><p>新版本根据用户的反馈增加了几个功能。稳定的内核版本现在已经升级到 5.15.24，并修复几个错误，以加强系统安全性。</p><p>让我们来看看这个版本还有哪些新功能吧。</p><h4 id="linux-上有了面部解锁" tabindex="-1">Linux 上有了面部解锁 <a class="header-anchor" href="#linux-上有了面部解锁" aria-label="Permalink to “Linux 上有了面部解锁”">​</a></h4><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/04/face-unlock-deepin.jpg?w=900&amp;ssl=1" alt=""></p>',13)),p("p",null,[e[1]||(e[1]=t("是的，我知道 Linux 上早就有面部解锁的相关消息了。毕竟，我曾经写过一篇关于 ",-1)),i(s,{href:"https://itsfoss.com/face-unlock-ubuntu/"},{default:n(()=>[...e[0]||(e[0]=[t("在 Linux 发行版中使用类似 Howdy 的软件来支持面部解锁功能",-1)])]),_:1}),e[2]||(e[2]=t(" 的详细指南。",-1))]),e[22]||(e[22]=o('<p>然而，那些软件更多的是一种个性化定制，是为那些有经验的、爱折腾的用户准备的。</p><p>深度现在提供基于人脸的生物识别认证方法。它可以在有内置摄像头的笔记本电脑上工作。</p><p>你需要先在控制中心录入人脸信息，此后，你就可以用你的人脸 ID 登录系统。</p><h4 id="用户可在应用商店中反馈" tabindex="-1">用户可在应用商店中反馈 <a class="header-anchor" href="#用户可在应用商店中反馈" aria-label="Permalink to “用户可在应用商店中反馈”">​</a></h4><p>你现在可以直接在应用商店中提交对某个应用的反馈。</p><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/04/app-store-feedback-deepin.webp?resize=1568%2C980&amp;ssl=1" alt=""></p><p>这还不算完。当你有应用程序的安装和更新问题时，你可以在应用程序中直接向官方支持提交问题，并获得解决方案（如果开发者提供了的话）。</p><h4 id="改进的邮件应用" tabindex="-1">改进的邮件应用 <a class="header-anchor" href="#改进的邮件应用" aria-label="Permalink to “改进的邮件应用”">​</a></h4><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/04/deepin-mail-app.webp?w=900&amp;ssl=1" alt=""></p><p>深度邮件应用现在支持了自定义文件夹管理。它还可以在网络重新连接后自动接收邮件。邮件应用的框架和插件已经替换成了当下流行的 Vue + TinyMCE。</p><p>现在，你可以通过点击系统通知直接跳转到到新邮件。为提高工作效率，你可以置顶常用邮件与合并邮件。你也可以预览邮件附件。</p><h4 id="可以-钉住-的屏幕截图" tabindex="-1">可以“钉住”的屏幕截图 <a class="header-anchor" href="#可以-钉住-的屏幕截图" aria-label="Permalink to “可以“钉住”的屏幕截图”">​</a></h4><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/04/pinned-screenshots-deepin.webp?w=900&amp;ssl=1" alt=""></p><p>你现在可以使用内置的屏幕截图工具来“钉住”截图。这样一来，捕获的屏幕截图就会固定在其他应用程序窗口的顶部。从而，你可以同时使用其他应用程序，以提高你的工作效率。另外，置顶的屏幕截图是可以移动的。</p><h4 id="其他变化" tabindex="-1">其他变化 <a class="header-anchor" href="#其他变化" aria-label="Permalink to “其他变化”">​</a></h4><p>下面是 Deepin 20.5 新版本中的一些其他变化：</p><ul><li>Linux 稳定内核更新到了 5.15.24</li><li>可以为一个有线网络适配器设置多个 IP</li><li>优化了无线网络的密码认证交互</li><li>系统搜索现在可以使用文件类型和扩展名作为关键词</li><li>设备管理器允许你禁用或启用设备</li><li>浏览 docx 文件的文档查看器得到了性能优化</li></ul>',17)),p("p",null,[e[4]||(e[4]=t("还有许多我没有提到的小功能和改进。你可以在 ",-1)),i(s,{href:"https://www.deepin.org/en/2022/03/31/deepin-20-5/"},{default:n(()=>[...e[3]||(e[3]=[t("版本发布说明",-1)])]),_:1}),e[5]||(e[5]=t(" 中了解这些内容。",-1))]),e[23]||(e[23]=p("hr",null,null,-1)),p("p",null,[e[7]||(e[7]=t("via: ",-1)),i(s,{href:"https://news.itsfoss.com/deepin-os-20-5-release/"},{default:n(()=>[...e[6]||(e[6]=[t("https://news.itsfoss.com/deepin-os-20-5-release/",-1)])]),_:1})]),p("p",null,[e[12]||(e[12]=t("作者：",-1)),i(s,{href:"https://news.itsfoss.com/author/root/"},{default:n(()=>[...e[8]||(e[8]=[t("Abhishek",-1)])]),_:1}),e[13]||(e[13]=t(" 选题：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[9]||(e[9]=[t("lujun9972",-1)])]),_:1}),e[14]||(e[14]=t(" 译者：",-1)),i(s,{href:"https://github.com/lkxed"},{default:n(()=>[...e[10]||(e[10]=[t("lkxed",-1)])]),_:1}),e[15]||(e[15]=t(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[18]||(e[18]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:n(()=>[...e[17]||(e[17]=[t("Linux中国",-1)])]),_:1}),e[20]||(e[20]=t(" 荣誉推出",-1))])])}const C=l(d,[["render",m]]);export{k as __pageData,C as default};
